76	  public SuccessResponse reloadSegment(String tableName, String segmentName, boolean forceDownload,
77	      String targetInstance, HttpHeaders headers) {
78	    tableName = DatabaseUtils.translateTableName(tableName, headers);
79	    long startTimeMs = System.currentTimeMillis();
80	    segmentName = URIUtils.decode(segmentName);
81	    String tableNameWithType = getExistingTable(tableName, segmentName);
82	    Pair<Integer, String> msgInfo =
83	        _pinotHelixResourceManager.reloadSegment(tableNameWithType, segmentName, forceDownload, targetInstance);
84	    boolean zkJobMetaWriteSuccess = false;
85	    int numReloadMsgSent = msgInfo.getLeft();
86	    if (numReloadMsgSent > 0) {
87	      try {
88	        if (_pinotHelixResourceManager.addNewReloadSegmentJob(tableNameWithType, segmentName, targetInstance,
89	            msgInfo.getRight(), startTimeMs, numReloadMsgSent)) {
90	          zkJobMetaWriteSuccess = true;
91	        } else {
92	          LOG.error("Failed to add reload segment job meta into zookeeper for table: {}, segment: {}",
93	              tableNameWithType, segmentName);
94	        }
95	      } catch (Exception e) {
96	        LOG.error("Failed to add reload segment job meta into zookeeper for table: {}, segment: {}",
97	            tableNameWithType, segmentName, e);
98	      }
99	      return new SuccessResponse(
100	          String.format("Submitted reload job id: %s, sent %d reload messages. Job meta ZK storage status: %s",
101	              msgInfo.getRight(), numReloadMsgSent, zkJobMetaWriteSuccess ? "SUCCESS" : "FAILED"));
102	    }
103	    throw new ControllerApplicationException(LOG,
104	        String.format("Failed to find segment: %s in table: %s on %s", segmentName, tableName,
105	            targetInstance == null ? "every instance" : targetInstance), Response.Status.NOT_FOUND);
106	  }
