108	  public SuccessResponse reloadAllSegments(String tableName, String tableTypeStr, boolean forceDownload,
109	      String targetInstance, String instanceToSegmentsMapInJson, HttpHeaders headers)
110	      throws IOException {
111	    tableName = DatabaseUtils.translateTableName(tableName, headers);
112	    TableType tableTypeFromTableName = TableNameBuilder.getTableTypeFromTableName(tableName);
113	    TableType tableTypeFromRequest = Constants.validateTableType(tableTypeStr);
114	    // When rawTableName is provided but w/o table type, Pinot tries to reload both OFFLINE
115	    // and REALTIME tables for the raw table. But forceDownload option only works with
116	    // OFFLINE table currently, so we limit the table type to OFFLINE to let Pinot continue
117	    // to reload w/o being accidentally aborted upon REALTIME table type.
118	    // TODO: support to force download immutable segments from RealTime table.
119	    if (forceDownload && (tableTypeFromTableName == null && tableTypeFromRequest == null)) {
120	      tableTypeFromRequest = TableType.OFFLINE;
121	    }
122	    List<String> tableNamesWithType =
123	        ResourceUtils.getExistingTableNamesWithType(_pinotHelixResourceManager, tableName, tableTypeFromRequest, LOG);
124	    if (instanceToSegmentsMapInJson != null) {
125	      Map<String, List<String>> instanceToSegmentsMap =
126	          JsonUtils.stringToObject(instanceToSegmentsMapInJson, new TypeReference<>() {
127	          });
128	      Map<String, Map<String, Map<String, String>>> tableInstanceMsgData =
129	          reloadSegments(tableNamesWithType, forceDownload, instanceToSegmentsMap);
130	      if (tableInstanceMsgData.isEmpty()) {
131	        throw new ControllerApplicationException(LOG,
132	            String.format("Failed to find any segments in table: %s with instanceToSegmentsMap: %s", tableName,
133	                instanceToSegmentsMap), Response.Status.NOT_FOUND);
134	      }
135	      return new SuccessResponse(JsonUtils.objectToString(tableInstanceMsgData));
136	    }
137	    long startTimeMs = System.currentTimeMillis();
138	    Map<String, Map<String, String>> perTableMsgData = new LinkedHashMap<>();
139	    for (String tableNameWithType : tableNamesWithType) {
140	      Pair<Integer, String> msgInfo =
141	          _pinotHelixResourceManager.reloadAllSegments(tableNameWithType, forceDownload, targetInstance);
142	      int numReloadMsgSent = msgInfo.getLeft();
143	      if (numReloadMsgSent <= 0) {
144	        continue;
145	      }
