19	package org.apache.pinot.common.messages;
20	
21	import com.google.common.base.Preconditions;
22	import java.util.List;
23	import java.util.UUID;
24	import javax.annotation.Nullable;
25	import org.apache.commons.collections4.CollectionUtils;
26	import org.apache.helix.model.Message;
27	import org.apache.helix.zookeeper.datamodel.ZNRecord;
28	
29	
30	/**
31	 * This Helix message is sent from the controller to the servers when a request is received to reload an existing
32	 * segment.
33	 */
34	public class SegmentReloadMessage extends Message {
35	  public static final String RELOAD_SEGMENT_MSG_SUB_TYPE = "RELOAD_SEGMENT";
36	
37	  private static final String FORCE_DOWNLOAD_KEY = "forceDownload";
38	  private static final String SEGMENT_NAMES = "segmentNames";
39	  private static final String RELOAD_JOB_ID_KEY = "reloadJobId";
40	
41	  /**
42	   * This msg asks server to reload all segments in the given a table.
43	   *
44	   * @param tableNameWithType the table where the segments are from.
45	   * @param forceDownload     whether to download segments from deep store when reloading.
46	   */
47	  public SegmentReloadMessage(String tableNameWithType, boolean forceDownload) {
48	    this(tableNameWithType, null, forceDownload);
49	  }
50	
51	  /**
52	   * This msg asks server to reload a list of specified segments in the given a table.
53	   *
54	   * @param tableNameWithType the table where the segments are from.
55	   * @param segmentNames      a list of specified segments to reload, or null for all segments.
56	   * @param forceDownload     whether to download segments from deep store when reloading.
57	   */
58	  public SegmentReloadMessage(String tableNameWithType, @Nullable List<String> segmentNames, boolean forceDownload) {
59	    super(MessageType.USER_DEFINE_MSG, UUID.randomUUID().toString());
60	    setResourceName(tableNameWithType);
61	    setMsgSubType(RELOAD_SEGMENT_MSG_SUB_TYPE);
62	    // Give it infinite time to process the message, as long as session is alive
63	    setExecutionTimeout(-1);
64	
65	    ZNRecord znRecord = getRecord();
66	
67	    // Persisting the msg ID as the reload job ID.
68	    znRecord.setSimpleField(RELOAD_JOB_ID_KEY, getMsgId());
69	
70	    znRecord.setBooleanField(FORCE_DOWNLOAD_KEY, forceDownload);
71	    if (CollectionUtils.isNotEmpty(segmentNames)) {
72	      // TODO: use the new List field and deprecate the partition name in next release.
73	      setPartitionName(segmentNames.get(0));
74	      znRecord.setListField(SEGMENT_NAMES, segmentNames);
75	    }
76	  }
77	
78	  public SegmentReloadMessage(Message message) {
79	    super(message.getRecord());
80	    String msgSubType = message.getMsgSubType();
81	    Preconditions.checkArgument(msgSubType.equals(RELOAD_SEGMENT_MSG_SUB_TYPE),
82	        "Invalid message sub type: " + msgSubType + " for SegmentReloadMessage");
83	  }
84	
85	  public boolean shouldForceDownload() {
86	    return getRecord().getBooleanField(FORCE_DOWNLOAD_KEY, false);
87	  }
88	
89	  @Nullable
90	  public List<String> getSegmentList() {
91	    return getRecord().getListField(SEGMENT_NAMES);
92	  }
93	
94	  /**
95	   * Gets the reload job ID that was assigned when this reload operation was initiated on the controller.
96	   * This ID is preserved in the message payload and survives Helix's message cloning during distribution.
97	   *
98	   * @return the reload job ID, or null if not set (for backward compatibility with old messages)
99	   */
100	  @Nullable
101	  public String getReloadJobId() {
102	    return getRecord().getSimpleField(RELOAD_JOB_ID_KEY);
103	  }
104	}
