71	  private static double computeEstimatedRemainingTimeInMinutes(PinotTableReloadStatusResponse finalResponse,
72	      double timeElapsedInMinutes) {
73	    // Clamp to 0 to handle cases where successCount > totalSegmentCount (e.g. segments added after job started)
74	    int remainingSegments = Math.max(0, finalResponse.getTotalSegmentCount() - finalResponse.getSuccessCount());
