}", "newString": "  /**
   * Reloads the given instance-to-segments mapping for a single table. All the reload messages share a single job UUID,
   * and a single ZK job entry is recorded for the whole table storing the instance-to-segments mapping as JSON.
   *
   * @return a map from instance name to its reload metadata (numMessagesSent, reloadJobId and the ZK storage status).
   */
  private Map<String, Map<String, String>> reloadSegmentsForTable(String tableNameWithType, boolean forceDownload,
      Map<String, List<String>> instanceToSegmentsMap) {
    long startTimeMs = System.currentTimeMillis();
    String reloadJobId = UUID.randomUUID().toString();
    // If only one instance is being targeted, record it as the job's instance name.
    String targetInstance =
        instanceToSegmentsMap.size() == 1 ? instanceToSegmentsMap.keySet().iterator().next() : null;
    Map<String, Integer> instanceMsgCountMap =
        _pinotHelixResourceManager.reloadSegments(tableNameWithType, forceDownload, instanceToSegmentsMap, reloadJobId);
    Map<String, Map<String, String>> instanceMsgData = new HashMap<>();
    int totalNumReloadMsgSent = 0;
    for (Map.Entry<String, Integer> entry : instanceMsgCountMap.entrySet()) {
      int numReloadMsgSent = entry.getValue();
      if (numReloadMsgSent <= 0) {
        continue;
      }
      totalNumReloadMsgSent += numReloadMsgSent;
      Map<String, String> tableReloadMeta = new HashMap<>();
      tableReloadMeta.put("numMessagesSent", String.valueOf(numReloadMsgSent));
      tableReloadMeta.put("reloadJobId", reloadJobId);
      instanceMsgData.put(entry.getKey(), tableReloadMeta);
    }
    if (totalNumReloadMsgSent > 0) {
      // The distinct, sorted list of reloaded segments across all instances is stored as the job's segment names.
      Set<String> allSegments = new TreeSet<>();
      for (List<String> segments : instanceToSegmentsMap.values()) {
        allSegments.addAll(segments);
      }
      String segmentNamesStr = StringUtils.join(allSegments, SegmentNameUtils.SEGMENT_NAME_SEPARATOR);
      String status;
      try {
        String instanceToSegmentsMapJson = JsonUtils.objectToString(instanceToSegmentsMap);
        boolean success = _pinotHelixResourceManager.addNewReloadSegmentJob(tableNameWithType, segmentNamesStr,
            targetInstance, reloadJobId, startTimeMs, totalNumReloadMsgSent, instanceToSegmentsMapJson);
        status = success ? "SUCCESS" : "FAILED";
        if (!success) {
          LOG.error("Failed to add batch reload job meta into zookeeper for table: {}", tableNameWithType);
        }
      } catch (Exception e) {
        status = "FAILED";
        LOG.error("Failed to add batch reload job meta into zookeeper for table: {}", tableNameWithType, e);
      }
      String finalStatus = status;
      instanceMsgData.values().forEach(meta -> meta.put("reloadJobMetaZKStorageStatus", finalStatus));
    }
